import {
  ArrowLeft,
  ChevronLeft,
  ChevronRight,
  Eraser,
  Highlighter,
  LoaderCircle,
  Underline,
} from "lucide-react";
import type { CSSProperties } from "react";
import { useEffect, useState } from "react";
import { Navigate, useNavigate, useParams } from "react-router-dom";
import {
  READING_CHAPTERS,
  loadReadingChapter,
  readingChapterById,
} from "../../data/readingChapters";
import LineSidebar from "../reactbits/vendor/LineSidebar/LineSidebar";
import WarmTooltip, {
  WarmTooltipGroup,
} from "../reactbits/vendor/WarmTooltip/WarmTooltip";
import {
  loadReaderAnnotations,
  saveReaderAnnotations,
  type ReaderAnnotationType,
  type ReaderAnnotations,
} from "../../lib/readerAnnotations";
import "./reading.css";

export function ChapterReader() {
  const navigate = useNavigate();
  const { chapterId } = useParams();
  const chapter = readingChapterById(chapterId);
  const [paragraphs, setParagraphs] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [annotationMode, setAnnotationMode] = useState<
    "read" | "underline" | "highlight" | "eraser"
  >("read");
  const [annotations, setAnnotations] = useState<ReaderAnnotations>({});

  useEffect(() => {
    if (!chapter) return;
    let active = true;
    setLoading(true);
    setParagraphs([]);
    void loadReadingChapter(chapter.id)
      .then((nextParagraphs) => {
        if (active) setParagraphs(nextParagraphs);
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [chapter]);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: "smooth" });
    setAnnotations(chapterId ? loadReaderAnnotations(chapterId) : {});
  }, [chapterId]);

  if (!chapter) return <Navigate to="/reading" replace />;

  const chapterIndex = READING_CHAPTERS.findIndex(
    (entry) => entry.id === chapter.id,
  );
  const previous =
    chapterIndex > 0 ? READING_CHAPTERS[chapterIndex - 1] : undefined;
  const next =
    chapterIndex < READING_CHAPTERS.length - 1
      ? READING_CHAPTERS[chapterIndex + 1]
      : undefined;

  const toggleAnnotation = (index: number, type: ReaderAnnotationType | null) => {
    const key = `paragraph:${index}`;
    setAnnotations((current) => {
      const nextState = { ...current };
      if (!type || nextState[key] === type) delete nextState[key];
      else nextState[key] = type;
      if (chapterId) saveReaderAnnotations(chapterId, nextState);
      return nextState;
    });
  };

  return (
    <main className="chapter-reader" data-motion="enter">
      <header className="chapter-reader__topbar">
        <button
          type="button"
          className="chapter-reader__back"
          onClick={() => navigate("/reading")}
          aria-label="返回章节列表"
        >
          <ArrowLeft size={18} />
        </button>
        <span className="chapter-reader__topbar-copy">
          <strong>{chapter.title}</strong>
          <small>
            {chapter.author} · {chapter.chapter}
          </small>
        </span>
        <nav className="chapter-reader__pager" aria-label="章节切换">
          <button
            type="button"
            disabled={!previous}
            onClick={() =>
              previous && navigate(`/reading/${previous.id}`)
            }
            aria-label="上一章"
          >
            <ChevronLeft size={16} />
          </button>
          <small>
            {chapterIndex + 1} / {READING_CHAPTERS.length}
          </small>
          <button
            type="button"
            disabled={!next}
            onClick={() => next && navigate(`/reading/${next.id}`)}
            aria-label="下一章"
          >
            <ChevronRight size={16} />
          </button>
        </nav>
      </header>

      <aside className="chapter-reader__sidebar">
        <LineSidebar
          items={READING_CHAPTERS.map((entry) => entry.title)}
          defaultActive={chapterIndex}
          accentColor={chapter.accent}
          textColor="#7a817c"
          markerColor="#b8beb9"
          markerLength={46}
          maxShift={18}
          itemGap={18}
          fontSize={0.78}
          onItemClick={(index) => {
            const target = READING_CHAPTERS[index];
            if (target) navigate(`/reading/${target.id}`);
          }}
        />
      </aside>

      <article
        className="chapter-reader__article"
        aria-busy={loading}
        style={
          {
            "--reading-accent": chapter.accent,
            "--reading-secondary": chapter.secondary,
          } as CSSProperties
        }
      >
        <header className="chapter-reader__heading">
          <span>{chapter.chapter}</span>
          <h1>{chapter.title}</h1>
          <h2>{chapter.chapterTitle}</h2>
          <p>
            {chapter.zhTitle} · {chapter.author} ·{" "}
            {Math.max(1, Math.ceil(chapter.wordCount / 220))} min read
          </p>
        </header>

        <WarmTooltipGroup delay={300} warmWindow={220} travel={220}>
          <div className="chapter-reader__annotation-tools">
            {[
              {
                mode: "underline" as const,
                label: "段落下划线",
                icon: Underline,
              },
              {
                mode: "highlight" as const,
                label: "段落荧光",
                icon: Highlighter,
              },
              { mode: "eraser" as const, label: "擦除标注", icon: Eraser },
            ].map(({ mode, label, icon: Icon }) => (
              <WarmTooltip
                content={label}
                side="bottom"
                surfaceColor="#f5efe3"
                inkColor="#2a231e"
                radius={7}
                key={mode}
              >
                <button
                  type="button"
                  className={annotationMode === mode ? "is-active" : ""}
                  aria-label={label}
                  onClick={() =>
                    setAnnotationMode((current) =>
                      current === mode ? "read" : mode,
                    )
                  }
                >
                  <Icon size={15} />
                </button>
              </WarmTooltip>
            ))}
            <button
              type="button"
              onClick={() => {
                setAnnotations({});
                if (chapterId) saveReaderAnnotations(chapterId, {});
              }}
            >
              清除
            </button>
          </div>
        </WarmTooltipGroup>

        {loading ? (
          <div className="chapter-reader__loading" role="status">
            <LoaderCircle size={24} />
            正在打开章节
          </div>
        ) : (
          <div className="chapter-reader__paragraphs">
            {paragraphs.map((paragraph, index) => (
              <p
                key={`${chapter.id}-${index}`}
                className={
                  annotations[`paragraph:${index}`]
                    ? `is-${annotations[`paragraph:${index}`]}`
                    : undefined
                }
                onClick={() => {
                  if (annotationMode === "read") return;
                  toggleAnnotation(
                    index,
                    annotationMode === "eraser" ? null : annotationMode,
                  );
                }}
              >
                {paragraph}
              </p>
            ))}
          </div>
        )}

        <footer className="chapter-reader__footer">
          <button
            type="button"
            disabled={!previous}
            onClick={() =>
              previous && navigate(`/reading/${previous.id}`)
            }
          >
            <ChevronLeft size={17} />
            <span>
              <small>上一章</small>
              <strong>{previous?.title ?? "已是第一章"}</strong>
            </span>
          </button>
          <button
            type="button"
            disabled={!next}
            onClick={() => next && navigate(`/reading/${next.id}`)}
          >
            <span>
              <small>下一章</small>
              <strong>{next?.title ?? "已经读完"}</strong>
            </span>
            <ChevronRight size={17} />
          </button>
        </footer>
      </article>
    </main>
  );
}
